<?php
declare(strict_types=1);
function gc_storage():string {
 $dir=gc_settings()['storage_path']??'';
 if(!is_string($dir)||$dir===''||$dir[0]!=='/'||is_link($dir))throw new RuntimeException('PRIVATE_DOCUMENT_STORAGE_REQUIRED');
 if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('DOCUMENT_STORAGE_UNAVAILABLE');
 $real=realpath($dir);if($real===false)throw new RuntimeException('DOCUMENT_STORAGE_MUST_BE_PRIVATE');
 // CLI sets DOCUMENT_ROOT to an empty string; realpath('') incorrectly means cwd.
 $webRoots=[cfg()['public_dir']??''];if(PHP_SAPI!=='cli')$webRoots[]=$_SERVER['DOCUMENT_ROOT']??'';
 foreach($webRoots as $webRoot){if(!is_string($webRoot)||$webRoot==='')continue;$web=realpath($webRoot);if($web!==false&&str_starts_with($real.'/',rtrim($web,'/').'/'))throw new RuntimeException('DOCUMENT_STORAGE_MUST_BE_PRIVATE');}
 chmod($real,0700);return $real;
}
function gc_document_access(array $actor,string $issuer,array $roles):void {if($actor['is_staff']??false){if(!one('SELECT id FROM pg_issuers WHERE id=?',[$issuer]))throw new ApiError('Компания не найдена',404);return;}gc_member($actor,$issuer,$roles);}
function gc_document_route(string $route,string $method,array $d,array $actor):mixed {
 if($route==='documents/contract/'&&$method==='GET'){$issuer=(string)($_GET['issuerId']??'');gc_document_access($actor,$issuer,['owner','accountant']);$i=one('SELECT contract_number,contract_version FROM pg_issuers WHERE id=?',[$issuer]);$doc=one("SELECT * FROM pg_documents WHERE issuer_id=? AND kind='generated_contract' AND version=? ORDER BY created_at DESC LIMIT 1",[$issuer,$i['contract_version']]);if(!$doc)throw new ApiError('Сначала подготовьте договор',409);gc_send_document($doc,$i['contract_number'].'.docx');}
 if($route==='documents/prepare/'&&$method==='POST'){
  if($actor['is_staff']??false)gc_admin_guard('documents-prepare/','POST',$actor);
  $issuer=txt($d,'issuerId',36);gc_document_access($actor,$issuer,['owner','accountant']);$i=one('SELECT * FROM pg_issuers WHERE id=?',[$issuer]);$co=json_decode($i['company_json'],true,512,JSON_THROW_ON_ERROR);
  require_once __DIR__.'/giftcards-operations.php';$co=gc_validate_company($co);
  $template=__DIR__.'/giftcards-template.docx';$signature=gc_signature_config();$version=hash('sha256',file_get_contents($template).$i['company_json'].json_encode($signature).$i['contract_number']);
  $existing=one("SELECT * FROM pg_documents WHERE issuer_id=? AND kind='generated_contract' AND version=?",[$issuer,$version]);
  if(!$existing){$id=gc_uuid();$storage=$id.'.docx';$path=gc_storage().'/'.$storage;gc_generate_contract($template,$path,$i,$co,$signature);$hash=hash_file('sha256',$path);transact(function()use($id,$issuer,$version,$storage,$path,$hash,$actor,$signature){query("INSERT INTO pg_documents(id,issuer_id,kind,version,storage_name,original_name,mime,size_bytes,sha256,status,uploaded_by,created_at) VALUES(?,?,'generated_contract',?,?,?,?,?,?,?,?,?)",[$id,$issuer,$version,$storage,'agency-contract.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',filesize($path),$hash,$signature?'agent_signed':'draft',$actor['id'],now()]);query('UPDATE pg_issuers SET contract_version=?,contract_hash=?,contract_status=? WHERE id=?',[$version,$hash,$signature?'agent_signed':'draft',$issuer]);audit((int)$actor['id'],'gift_contract_generated',$id);});$existing=one('SELECT * FROM pg_documents WHERE id=?',[$id]);}
  return ['id'=>$existing['id'],'status'=>$existing['status'],'downloadUrl'=>'/api/gift/documents/contract/?issuerId='.$issuer];
 }
 if($route==='documents/upload/'&&$method==='POST'){
  if($actor['is_staff']??false)gc_admin_guard('supplier-save/','POST',$actor);
  $issuer=txt($d,'issuerId',36);gc_document_access($actor,$issuer,['owner']);$i=one('SELECT * FROM pg_issuers WHERE id=?',[$issuer]);if(!$i['contract_hash'])throw new ApiError('Сначала подготовьте действующую редакцию договора');
  $file=$_FILES['file']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']<8||$file['size']>10*1024*1024||!is_uploaded_file($file['tmp_name']))throw new ApiError('Загрузите PDF или DOCX размером до 10 МБ');
  $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext='';
  if($mime==='application/pdf'&&str_starts_with(file_get_contents($file['tmp_name'],false,null,0,5),'%PDF-'))$ext='pdf';
  else{$z=new ZipArchive();if($z->open($file['tmp_name'])===true){$bytes=0;for($n=0;$n<$z->numFiles;$n++)$bytes+=(int)$z->statIndex($n)['size'];if($z->numFiles<500&&$bytes<=25*1024*1024&&$z->locateName('word/document.xml')!==false&&$z->locateName('[Content_Types].xml')!==false){$ext='docx';$mime='application/vnd.openxmlformats-officedocument.wordprocessingml.document';}$z->close();}}
  if($ext==='')throw new ApiError('Формат файла не подтверждён. Допустимы PDF или DOCX');
  $id=gc_uuid();$storage=$id.'.'.$ext;$target=gc_storage().'/'.$storage;if(!move_uploaded_file($file['tmp_name'],$target))throw new RuntimeException('UPLOAD_SAVE_FAILED');chmod($target,0600);$hash=hash_file('sha256',$target);
  try{transact(function()use($id,$issuer,$i,$storage,$target,$hash,$mime,$actor,$ext){query("INSERT INTO pg_documents(id,issuer_id,kind,version,storage_name,original_name,mime,size_bytes,sha256,status,uploaded_by,created_at) VALUES(?,?,'signed_contract',?,?,?,?,?,?,'review',?,?)",[$id,$issuer,$i['contract_version'],$storage,'signed-contract.'.$ext,$mime,filesize($target),$hash,$actor['id'],now()]);query("UPDATE pg_issuers SET contract_status='review',status='review',updated_at=? WHERE id=?",[now(),$issuer]);audit((int)$actor['id'],'gift_signed_contract_uploaded',$id);});}catch(Throwable $e){unlink($target);throw $e;}
  return ['id'=>$id,'status'=>'review'];
 }
 if($route==='documents/list/'&&$method==='GET'){$issuer=(string)($_GET['issuerId']??'');gc_document_access($actor,$issuer,['owner','accountant']);return ['items'=>rows('SELECT id,kind,version,original_name,mime,size_bytes,sha256,status,created_at FROM pg_documents WHERE issuer_id=? ORDER BY created_at DESC',[$issuer])];}
 if($route==='documents/download/'&&$method==='GET'){$id=(string)($_GET['id']??'');$doc=one('SELECT * FROM pg_documents WHERE id=?',[$id]);if(!$doc)throw new ApiError('Документ не найден',404);if(!(int)$actor['is_staff'])gc_member($actor,$doc['issuer_id'],['owner','accountant']);gc_send_document($doc,$doc['original_name']);}
 throw new ApiError('Метод не найден',404);
}
function gc_send_document(array $doc,string $name):never {$path=gc_storage().'/'.$doc['storage_name'];if(!is_file($path)||!hash_equals($doc['sha256'],hash_file('sha256',$path)))throw new ApiError('Не удалось проверить документ',503);header('Content-Type: '.$doc['mime']);header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9_.-]/','_',$name).'"');header('Content-Length: '.filesize($path));header('Cache-Control: private, no-store');readfile($path);exit;}
function gc_signature_config():?array {
 $s=gc_settings();if(!($s['agent_signature_approved']??false))return null;$path=$s['agent_signature_path']??'';$hash=$s['agent_signature_sha256']??'';
 if(!is_string($path)||!is_file($path)||is_link($path)||strlen($hash)!==64||!hash_equals($hash,hash_file('sha256',$path))||filesize($path)>1048576)throw new RuntimeException('APPROVED_SIGNATURE_REQUIRED');
 $size=getimagesize($path);if(!$size||$size[2]!==IMAGETYPE_PNG||$size[0]<1||$size[1]<1||$size[0]>6000||$size[1]>2000)throw new RuntimeException('SIGNATURE_MUST_BE_PNG');
 return ['path'=>$path,'hash'=>$hash,'width'=>$size[0],'height'=>$size[1]];
}
function gc_generate_contract(string $template,string $target,array $issuer,array $co,?array $signature):void {
 if(!copy($template,$target))throw new RuntimeException('CONTRACT_COPY_FAILED');chmod($target,0600);$zip=new ZipArchive();if($zip->open($target)!==true)throw new RuntimeException('CONTRACT_TEMPLATE_INVALID');
 try{$xml=$zip->getFromName('word/document.xml');$dom=new DOMDocument();if(!$dom->loadXML($xml,LIBXML_NONET))throw new RuntimeException('INVALID_DOCUMENT_XML');$ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main';$xp=new DOMXPath($dom);$xp->registerNamespace('w',$ns);
  $get=static fn(DOMNode $node):string=>implode('',array_map(static fn($t)=>$t->textContent,iterator_to_array($xp->query('.//w:t',$node))));
  $set=static function(DOMNode $node,string $value)use($xp,$dom,$ns){$texts=iterator_to_array($xp->query('.//w:t',$node));if(!$texts)return;foreach(iterator_to_array($xp->query('.//w:br',$node)) as $br)$br->parentNode->removeChild($br);$lines=explode("\n",$value);$texts[0]->textContent=array_shift($lines);foreach(array_slice($texts,1) as $t)$t->textContent='';foreach($lines as $line){$texts[0]->parentNode->appendChild($dom->createElementNS($ns,'w:br'));$t=$dom->createElementNS($ns,'w:t');$t->textContent=$line;$texts[0]->parentNode->appendChild($t);}};
  $day=gmdate('d.m.Y');foreach(iterator_to_array($xp->query('//w:p')) as $p){$t=$get($p);$new=$t;if(str_starts_with($t,'Договор №'))$new='Договор № '.$issuer['contract_number'].'     Место заключения Ереван     Дата '.$day.($signature?'':' — ПРОЕКТ БЕЗ ПОДПИСИ');elseif(str_contains($t,'и [полное наименование эмитента]'))$new=str_replace(['[полное наименование эмитента]','регистрационный номер [номер]','налоговый номер [номер]','[должность и ФИО]','[основание полномочий]'],[$co['name'],'регистрационный номер '.$co['reg'],'налоговый номер '.$co['tax'],$co['role'].' '.$co['director'],$co['authority']],$t);elseif(str_starts_with($t,'К Договору №'))$new=str_replace(['[номер]','[дата]'],[$issuer['contract_number'],$day],$t);if(str_contains($new,'Эмитент: __________________ / [ФИО]'))$new="Агент: __________________ / Усенков П. А.\nЭмитент: __________________ / ".$co['director'];if($new!==$t)$set($p,$new);}
  $tables=$xp->query('//w:tbl');$cells=$xp->query('.//w:tc',$tables->item(0));$set($cells->item(3),$co['name']."\nСтрана: Кыргызская Республика\nРег. № ".$co['reg']."\nНалоговый № ".$co['tax']."\nАдрес: ".$co['address']."\nБанковские реквизиты: Приложение 1\nЭлектронная почта: ".$co['email']."\nТелефон: ".$co['phone']);$set($cells->item(5),$co['role']."\n".$co['director']."\nПодпись __________________");
  $values=['Эмитент и фактический поставщик'=>$co['name'].', рег. № '.$co['reg'].', налоговый № '.$co['tax'].', '.$co['address'].', '.$co['email'].', '.$co['phone'].'. Эмитент является стороной основного договора и отвечает за привлеченных им исполнителей.','Товары или услуги и место исполнения'=>$co['goods'].'. Территория: Кыргызская Республика. Фактическое место передачи товара или оказания услуги: '.($co['fulfillmentAddress']??'[указать фактический адрес]').'. Получение товара, доставка покупателю и оказание услуг в Российской Федерации по этой программе не предусмотрены. Электронные услуги в программу не входят.','Правила карты и основного договора'=>$co['rules'].'. Применимая редакция согласуется до открытия продаж и сохраняется для каждого заказа.','Номиналы и валюта'=>'10 000, 50 000, 100 000, 500 000, 1 000 000 и 5 000 000 RUB. Цена для покупателя равна номиналу. Доступность и ограничения согласуются до открытия продаж.','Выпуск и действие'=>'Срок выпуска: '.$co['issueTime'].'. Срок запроса: '.$co['requestTime'].'. Срок действия: '.$co['validity'].'. Истечение срока не исключает обязательных денежных требований.','Погашение'=>$co['redemption'].'. При погашении фиксируются ФИО покупателя и основной договор или заказ в реестре. Отдельный агентский договор с покупателем не нужен.','Банк и счет Эмитента'=>$co['bank'].'. Получатель: '.$co['name'].'. Счет / IBAN: '.$co['account'].'. SWIFT / банковский код: '.$co['swift'].'. Другой получатель допускается только по пункту 6.3.','Подтверждение зачисления'=>'Банковская выписка или подтверждение банка получателя через согласованный защищенный канал в течение одного рабочего дня после получения или запроса.','Периодичность и комиссии'=>'Перечисление по пункту 6.1. Вознаграждение Агента — 0,1%. Валютный контроль — 0,2%, перевод — 0,6%. База — номинал погашенных карт до удержаний. Расходы подтверждаются банковскими документами и сверяются. Конвертация отсутствует; расчёты в RUB. Изменения требуют письменного соглашения.','Обеспечение'=>'Не применяется. Изменения оформляются отдельным письменным соглашением.','Связь и обмен подтверждениями'=>'Агент: mail@pina.market; +7 977 852 58 10; https://pina.market. Ответственный: Усенков Павел Александрович. Эмитент: '.$co['email'].'; '.$co['director'].'; '.$co['phone'].'. Защищенный канал: '.$co['exchangeChannel']];
  foreach($xp->query('.//w:tr',$tables->item(1)) as $row){$cs=$xp->query('./w:tc',$row);if($cs->length===2&&isset($values[$get($cs->item(0))]))$set($cs->item(1),$values[$get($cs->item(0))]);}
  if($signature)gc_embed_signature($zip,$dom,$cells->item(4),$signature,$ns);
  $zip->addFromString('word/document.xml',$dom->saveXML());
 }finally{$zip->close();}
}
function gc_embed_signature(ZipArchive $zip,DOMDocument $dom,DOMNode $cell,array $image,string $ns):void {
 // The PNG is approved and hashed in private configuration. It is never served as a public asset.
 $zip->addFile($image['path'],'word/media/pina-approved-signature.png');$rels=new DOMDocument();$rels->loadXML($zip->getFromName('word/_rels/document.xml.rels'),LIBXML_NONET);$rel=$rels->createElementNS('http://schemas.openxmlformats.org/package/2006/relationships','Relationship');$rel->setAttribute('Id','rIdPinaApprovedSignature');$rel->setAttribute('Type','http://schemas.openxmlformats.org/officeDocument/2006/relationships/image');$rel->setAttribute('Target','media/pina-approved-signature.png');$rels->documentElement->appendChild($rel);$zip->addFromString('word/_rels/document.xml.rels',$rels->saveXML());
 $types=new DOMDocument();$types->loadXML($zip->getFromName('[Content_Types].xml'),LIBXML_NONET);$found=false;foreach($types->getElementsByTagName('Default') as $n)if($n->getAttribute('Extension')==='png')$found=true;if(!$found){$el=$types->createElementNS('http://schemas.openxmlformats.org/package/2006/content-types','Default');$el->setAttribute('Extension','png');$el->setAttribute('ContentType','image/png');$types->documentElement->appendChild($el);$zip->addFromString('[Content_Types].xml',$types->saveXML());}
 $height=max(120000,min(480000,(int)(1440000*$image['height']/$image['width'])));$fragment=$dom->createDocumentFragment();$drawing='<w:p xmlns:w="'.$ns.'"><w:r><w:drawing><wp:inline xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" distT="0" distB="0" distL="0" distR="0"><wp:extent cx="1440000" cy="'.$height.'"/><wp:docPr id="9001" name="Подпись Pina Market"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="0" name="Pina Market"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="rIdPinaApprovedSignature"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="1440000" cy="'.$height.'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>';
 if(!$fragment->appendXML($drawing))throw new RuntimeException('SIGNATURE_EMBED_FAILED');$cell->appendChild($fragment);
}
